return {["scripts/items/mist_tunic.lua"]={["Path"]="scripts/items/mist_tunic.lua",["SHA256"]="5a34ae4e58e665a164cfc53daa6f0dbdf5b88cfcc468c823e0873d40c774d922",["Text"]="-----------------------------------\n-- ID: 14423\n-- Item: Mist Tunic\n-- Item Effect: Evasion Boost\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.EVASION_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIST_TUNIC) ~= nil then\n        target:delStatusEffect(xi.effect.EVASION_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MIST_TUNIC)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.MIST_TUNIC) then\n        if not target:hasStatusEffect(xi.effect.EVASION_BOOST) then\n            target:addStatusEffect(xi.effect.EVASION_BOOST, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.MIST_TUNIC })\n        else\n            target:messageBasic(xi.msg.basic.NO_EFFECT)\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.EVA, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mistmelt.lua"]={["Path"]="scripts/items/mistmelt.lua",["SHA256"]="c2f93785575b9f0c44d6766d5b48cff8d93e3055cc0bf7fd07b8e620124cafc5",["Text"]="-----------------------------------\n-- ID: 5265\n-- Item: Mistmelt\n-- Item Effect: Forces Ouryu to land\n-----------------------------------\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, param, player)\n    local result = 0\n\n    if target:getName() ~= 'Ouryu' then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:checkDistance(player) > 10 then\n        result = xi.msg.basic.TOO_FAR_AWAY\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, player)\n    if target:getAnimationSub() == 1 then\n        target:setLocalVar('mistmeltUsed', 1)\n    end\nend\n\nreturn itemObject\n"},["scripts/items/mithra_snare.lua"]={["Path"]="scripts/items/mithra_snare.lua",["SHA256"]="d227240091a282975f8fabce6e78521621c33805ae7f082e8effc5439aad6760",["Text"]="-----------------------------------\n-- ID: 5330\n-- Item: Mithra snare\n-- Used in Pirates Chart quest\n-- When used on one of the quest nms, prevents its use of 2hr\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.piratesChart.onItemCheck(target, item, caster)\nend\n\nitemObject.onItemUse = function(target)\n    target:setLocalVar('usedTwoHour', 1)\nend\n\nreturn itemObject\n"},["scripts/items/mithran_rice_cake.lua"]={["Path"]="scripts/items/mithran_rice_cake.lua",["SHA256"]="ae5cdf90d75e00d22c79963fe5b30a94733a8ad0d24766f1bdde6b0b4bfa35b6",["Text"]="-----------------------------------\n-- ID: 5297\n-- Mithran Rice Cake\n-- Enchantment: 60Min, Costume - Mithra Child\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 182, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/mithran_tomato.lua"]={["Path"]="scripts/items/mithran_tomato.lua",["SHA256"]="6aa4b3ab29abd36bcb001abdb4a255d91b7fe5164a7964a3921c82c2bb93b644",["Text"]="-----------------------------------\n-- ID: 4390\n-- Item: mithran_tomato\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility -3\n-- Intelligence 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, -3)\n    effect:addMod(xi.mod.INT, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/moat_carp.lua"]={["Path"]="scripts/items/moat_carp.lua",["SHA256"]="fddd2b406df164868c9193d935a41814bcf7de936b46d6d1626d9b3b249a7fa4",["Text"]="-----------------------------------\n-- ID: 4401\n-- Item: moat_carp\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mog_missile.lua"]={["Path"]="scripts/items/mog_missile.lua",["SHA256"]="925dc4dc1d3b61380e7aa26e2c1f87f258dcdd8531b4c28ac2c3e86a4078b024",["Text"]="-----------------------------------\n-- ID: 5936\n-- Mog Missile\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/moggiebag.lua"]={["Path"]="scripts/items/moggiebag.lua",["SHA256"]="b96ccee4922f1fee15789ba3cc3eef988537e1e4a5e46601cb7a65b619eddae1",["Text"]="-----------------------------------\n-- ID: 19246\n-- Item: Moggiebag\n-- Moogle's secret cache dispenses between 100 and 10,000 gil.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    local amount = math.randomInt(100, 10000)\n    npcUtil.giveCurrency(target, 'gil', amount)\nend\n\nreturn itemObject\n"},["scripts/items/mokusa.lua"]={["Path"]="scripts/items/mokusa.lua",["SHA256"]="7e94c34866bcc23b28a0740cd23cf7b5ad14e5bc2a748d217106eb2e8d5b2ebf",["Text"]="-----------------------------------\n-- ID: 18359\n-- Item: Mokusa\n-- Additional effect: Wind damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\n-- Made up values\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance          = 5,\n        basePower       = 19,\n        attackType      = xi.attackType.MAGICAL,\n        magicalElement  = xi.element.WIND,\n        canResist       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/monk_die.lua"]={["Path"]="scripts/items/monk_die.lua",["SHA256"]="5482b48dcf7e6a06f5fc415f2a4d8a2605f5a09cb56a0c3a311b1a4acbfa224d",["Text"]="-----------------------------------\n-- ID: 5478\n-- Monk Die\n-- Teaches the job ability Monk's Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.MONKS_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.MONKS_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/montagna.lua"]={["Path"]="scripts/items/montagna.lua",["SHA256"]="3fbe1a20a51d89e75c0a31aed9f55578e19aa56a7b3df86a9b48ffe4f8e78b23",["Text"]="-----------------------------------\n-- ID: 5887\n-- Item: montagna\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP +8% (cap 140)\n-- Increases rate of combat skill gains by 60%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 8)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 140)\n    effect:addMod(xi.mod.COMBAT_SKILLUP_RATE, 60)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/moogle_cap.lua"]={["Path"]="scripts/items/moogle_cap.lua",["SHA256"]="b55a2c8eecb5993207a85491b8d647989c2a1f429a38d1aeb5109ec3ff4ef2fc",["Text"]="-----------------------------------\n--  ID: 16118\n--  Moogle Cap\n--  Transports the user to their Home Nation\n-----------------------------------\nrequire('scripts/globals/teleports')\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.HOME_NATION, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/moogle_pie.lua"]={["Path"]="scripts/items/moogle_pie.lua",["SHA256"]="b539286b0d186ddcd55f8a57948ad21b77625b13072f4a6d981de52e62a78e48",["Text"]="-----------------------------------\n-- ID: 5561\n-- Item: Moogle Pie\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- HP 20\n-- MP 20\n-- Strength 1\n-- Dexterity 1\n-- Vitality 1\n-- Agility 1\n-- Intelligence 1\n-- Mind 1\n-- Charisma 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 20)\n    effect:addMod(xi.mod.FOOD_MP, 20)\n    effect:addMod(xi.mod.STR, 1)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.INT, 1)\n    effect:addMod(xi.mod.MND, 1)\n    effect:addMod(xi.mod.CHR, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/moogle_suit.lua"]={["Path"]="scripts/items/moogle_suit.lua",["SHA256"]="f3cd6547201f33e23724f366fa279a6e5df8ea1a8ca1f3321dbac59c00704943",["Text"]="-----------------------------------\n-- ID: 10250\n-- Moogle Suit\n-- Dispense: Mog Missile\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.MOG_MISSILE, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/moon_ball.lua"]={["Path"]="scripts/items/moon_ball.lua",["SHA256"]="848a8372e0543b393bafdc54dfe9c4ad171ae49aa178178177deb38de761be86",["Text"]="-----------------------------------\n-- ID: 4568\n-- Item: moon_ball\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Health 3\n-- Magic 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 3)\n    effect:addMod(xi.mod.FOOD_MP, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/moon_carrot.lua"]={["Path"]="scripts/items/moon_carrot.lua",["SHA256"]="63b420fb93ff6535bfe521cf29cf354657e687add3dd5d5964e1f00395bfbd06",["Text"]="-----------------------------------\n-- ID: 4567\n-- Item: moon_carrot\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- Agility 1\n-- Vitality -1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 1)\n    effect:addMod(xi.mod.VIT, -1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/moorish_idol.lua"]={["Path"]="scripts/items/moorish_idol.lua",["SHA256"]="588fb4517220fdad5aab827f0baabd9f68601dfccde2a4502eeb1a0bb6c51b54",["Text"]="-----------------------------------\n-- ID: 5121\n-- Item: Moorish Idol\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/moranas_pigaches.lua"]={["Path"]="scripts/items/moranas_pigaches.lua",["SHA256"]="1575bd5d5b290fac81347ee9a11779cb73e1d3100fd0aa097b38b191c6344540",["Text"]="-----------------------------------\n-- ID: 11408\n-- Morana Pigaches\n-- Pet mod via latent effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\nlocal listenerPrefix = 'PET_MOD_LATENT'\nlocal latentPetId = xi.petId.SHIVA\nlocal latentMods =\n{\n    { xi.mod.MACC, 6 },\n}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemEquip  = function(user, item)\n    local listenerName = fmt('{}_{}', listenerPrefix, item:getID())\n    xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, true)\n\n    user:addListener('MAGIC_STATE_EXIT', listenerName, function(player, spell)\n        if spell:getSpellGroup() == xi.magic.spellGroup.SUMMONING then\n            xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, true)\n        end\n    end)\nend\n\nitemObject.onItemUnequip = function(user, item)\n    local listenerName = fmt('{}_{}', listenerPrefix, item:getID())\n    xi.itemUtils.handlePetLatentMods(user, latentPetId, latentMods, false)\n\n    user:removeListener(listenerName)\nend\n\nreturn itemObject\n"},["scripts/items/mug_of_honeyed_egg.lua"]={["Path"]="scripts/items/mug_of_honeyed_egg.lua",["SHA256"]="518fb51be7da8a576759caa2f5daacb856263a12589f8cffdb99cf9af008edd5",["Text"]="-----------------------------------\n-- ID: 5739\n-- Item: mug_of_honeyed_egg\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- MP 8\n-- Intelligence 1\n-- MP recovered while healing 1\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 8)\n    effect:addMod(xi.mod.INT, 1)\n    effect:addMod(xi.mod.MPHEAL, 1)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/muketsu.lua"]={["Path"]="scripts/items/muketsu.lua",["SHA256"]="9f6121a4f06430fddb81ee22541a7480697aad5dc6ca9b6e3162c1373a307c5b",["Text"]="-----------------------------------\n-- ID: 17778\n-- Item: Muketsu\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = xi.additionalEffect.linearProcRate(dStat, 32, 8, 13),\n        basePower       = 8 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.SLASHING,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/muketsu_+1.lua"]={["Path"]="scripts/items/muketsu_+1.lua",["SHA256"]="aaf16b8c51e2a64fbc915b729005b722227b8c3842484af6830aa1331540197c",["Text"]="-----------------------------------\n-- ID: 17779\n-- Item: Muketsu +1\n-- Additional effect: en-drain\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance          = xi.additionalEffect.linearProcRate(dStat, 32, 8, 13),\n        basePower       = 8 + utils.clamp(dStat, -3, 16) + utils.clamp(math.floor((dStat - 16) / 2), 0, 16),\n        attackType      = xi.attackType.PHYSICAL,\n        physicalElement = xi.damageType.SLASHING,\n        magicalElement  = xi.element.DARK,\n        canResist       = true,\n        lowestResist    = 0.5,\n        limitUndead     = true,\n        drainHP         = true,\n        overDrain       = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/murasame.lua"]={["Path"]="scripts/items/murasame.lua",["SHA256"]="6c1fd38dd33101496495d42dde6d57bec427826866903880488b6a6799c03f6b",["Text"]="-----------------------------------\n-- ID: 16961\n-- Item: Murasame\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 15,\n        basePower      = math.randomInt(12, 16),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/mushroom_crepe.lua"]={["Path"]="scripts/items/mushroom_crepe.lua",["SHA256"]="7c9e2f4555acdf09a8cca5b167945dba3d7d0a56ec31952e284d408ec9c60dfb",["Text"]="-----------------------------------\n-- ID: 5773\n-- Item: mushroom_crepe\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Mind 2\n-- MP % 10 (cap 30)\n-- Magic Accuracy +10\n-- Magic Def. Bonus +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MND, 2)\n    effect:addMod(xi.mod.FOOD_MPP, 10)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 30)\n    effect:addMod(xi.mod.MACC, 10)\n    effect:addMod(xi.mod.MDEF, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mushroom_salad.lua"]={["Path"]="scripts/items/mushroom_salad.lua",["SHA256"]="93ddc535ccaf5f523f2433f26d481bb4b6d9633fbf49a435794348cb61e0d230",["Text"]="-----------------------------------\n-- ID: 5678\n-- Item: Mushroom Salad\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- MP 14% Cap 85\n-- Agility 6\n-- Mind 6\n-- Strength -5\n-- Vitality -5\n-- Ranged Accuracy +15\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MPP, 14)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 85)\n    effect:addMod(xi.mod.AGI, 6)\n    effect:addMod(xi.mod.MND, 6)\n    effect:addMod(xi.mod.STR, -5)\n    effect:addMod(xi.mod.VIT, -5)\n    effect:addMod(xi.mod.RACC, 15)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/muteppo.lua"]={["Path"]="scripts/items/muteppo.lua",["SHA256"]="bc465d78482d4cdf9181520a4fb8d5ccc22f1998e12745d36381e16f7d8b3d41",["Text"]="-----------------------------------\n-- ID: 5360\n-- Muteppo\n-- A roman candle-like firework that hurls different colors\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\nend\n\nreturn itemObject\n"},["scripts/items/mutton_enchilada.lua"]={["Path"]="scripts/items/mutton_enchilada.lua",["SHA256"]="20ad2b9b69fa90d5c349fb1fb1e0c7c1a2c4cdd97c9b2ec9072a66523408846e",["Text"]="-----------------------------------\n-- ID: 4348\n-- Item: mutton_enchilada\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Magic 10\n-- Strength 3\n-- Vitality 1\n-- Intelligence -1\n-- Attack % 27\n-- Attack Cap 35\n-- Ranged ATT % 27\n-- Ranged ATT Cap 35\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 10)\n    effect:addMod(xi.mod.STR, 3)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.INT, -1)\n    effect:addMod(xi.mod.FOOD_ATTP, 27)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 35)\n    effect:addMod(xi.mod.FOOD_RATTP, 27)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 35)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mutton_tortilla.lua"]={["Path"]="scripts/items/mutton_tortilla.lua",["SHA256"]="65041171273668c9a7a4edb5fd60cfc11b95f8965f082ecd316f0a8cce8d61a7",["Text"]="-----------------------------------\n-- ID: 4506\n-- Item: mutton_tortilla\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Magic 10\n-- Strength 3\n-- Vitality 1\n-- Intelligence -1\n-- Attack % 27\n-- Attack Cap 30\n-- Ranged ATT % 27\n-- Ranged ATT Cap 30\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 10)\n    effect:addMod(xi.mod.STR, 3)\n    effect:addMod(xi.mod.VIT, 1)\n    effect:addMod(xi.mod.INT, -1)\n    effect:addMod(xi.mod.FOOD_ATTP, 27)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 30)\n    effect:addMod(xi.mod.FOOD_RATTP, 27)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 30)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mythril_bolt_quiver.lua"]={["Path"]="scripts/items/mythril_bolt_quiver.lua",["SHA256"]="99895517782001def5b5509272628bd6e00a038c83d6586581bcf30cd88f4ad5",["Text"]="-----------------------------------\n-- ID: 4228\n-- Mythril Bolt Quiver\n-- When used, you will obtain one stack of Mythril Bolts\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.MYTHRIL_BOLT, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/nadrs.lua"]={["Path"]="scripts/items/nadrs.lua",["SHA256"]="729c2c52b52b5200384a5dc2fbc3d7a9545487dd922af2a7e54ec4065458a61b",["Text"]="-----------------------------------\n-- ID: 17650\n-- Item: Nadrs\n-- Additional effect: poison\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local dStat  = actor:getStat(xi.mod.INT) - target:getStat(xi.mod.INT)\n\n    local pTable =\n    {\n        chance       = 3.5 + utils.clamp(dStat / 2, 0, 21.5), -- 3.5% + 1% per 2 INT based on the data. Unknown if there are knees that may increase rate a bit\n        effectId     = xi.effect.POISON,\n        power        = 2,                   -- Tested in Brenner\n        duration     = math.random(30, 60), -- TODO: needs more research\n    }\n\n    return xi.combat.action.executeAddEffectEnfeeblement(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/naruko_earring.lua"]={["Path"]="scripts/items/naruko_earring.lua",["SHA256"]="d04bf1cefa4cfd8b1390600531cc411e39f40f08a881fed8829d7cc5407fde00",["Text"]="-----------------------------------\n-- ID: 14789\n-- Item: Naruko Earring\n-- Item Effect: Enmity +10\n-- Duration: 3 Minutes\n-- https://wiki.ffo.jp/html/10069.html\n-- TODO: Capture Icon\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.NARUKO_EARRING) then\n        local effect = target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.NARUKO_EARRING)\n        if effect then\n            effect:resetStartTime()\n        else\n            target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.NARUKO_EARRING })\n        end\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.ENMITY, 10)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.NARUKO_EARRING)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/narval.lua"]={["Path"]="scripts/items/narval.lua",["SHA256"]="40c49381e96016ccabba31f31e0974b78556d01c73ce69021f5f834c9681f0d7",["Text"]="-----------------------------------\n-- ID: 16884\n-- Item: Narval\n-- Additional effect: water damage vs undead\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    if target:getEcosystem() ~= xi.ecosystem.UNDEAD then\n        return 0, 0, 0\n    end\n\n    local dStat  = actor:getStat(xi.mod.MND) - target:getStat(xi.mod.MND)\n    local power  = 13 + utils.clamp(dStat, 0, 60)\n    local pTable =\n    {\n        chance         = 10 + utils.clamp(dStat * 0.741, 1, 40), -- Averaged over the whole range, 10 + 0-40% with dMND\n        basePower      = math.randomInt(power, power + 7),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/nashmau_earring.lua"]={["Path"]="scripts/items/nashmau_earring.lua",["SHA256"]="03e94f7a1a7e2c3e3d3bb253c7ec460e94d48580e1ceb3e8acef3874f8890045",["Text"]="-----------------------------------\n-- ID: 16050\n-- Nashmau Earring\n-- Enchantment: \"Teleport\" (Nashmau)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.NASHMAU_EARRING, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/naval_rice_ball.lua"]={["Path"]="scripts/items/naval_rice_ball.lua",["SHA256"]="56036244ef8e1c525d094c9db6a068dd207c4946bc29853a876856e5f2250806",["Text"]="-----------------------------------\n-- ID: 4605\n-- Item: Naval Rice Ball\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- HP +12\n-- Dex +3\n-- Vit +3\n-- hHP +2\n-- Effect with enhancing equipment (Note: these are latents on gear with the effect)\n-- Atk +40\n-- Def +40\n-- Aquan Killer +4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 12)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.VIT, 3)\n    effect:addMod(xi.mod.HPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/navy_axe.lua"]={["Path"]="scripts/items/navy_axe.lua",["SHA256"]="ecedcce8bfe4e70749780d4654e3fb557eccc0aed901bb475c462872f6c4f7e3",["Text"]="-----------------------------------\n-- ID: 17957\n-- Item: Navy Axe\n-- Item Effect: TP +1000\n-- Duration: Instant\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addTP(1000)\nend\n\nreturn itemObject\n"},["scripts/items/nebimonite.lua"]={["Path"]="scripts/items/nebimonite.lua",["SHA256"]="83689643295a550a13e8b20be50e72edb52960034690e9fafe82bc8437093e2d",["Text"]="-----------------------------------\n-- ID: 4361\n-- Item: nebimonite\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity -3\n-- Vitality 2\n-- Defense % 13 (cap 50)\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -3)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.FOOD_DEFP, 13)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 50)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/nebimonite_bake.lua"]={["Path"]="scripts/items/nebimonite_bake.lua",["SHA256"]="589ff0e26c1084d5e6083f4d1afc1d8feaf90c050411ccdcea460f98323afee0",["Text"]="-----------------------------------\n-- ID: 4459\n-- Item: nebimonite_bake\n-- Food Effect: 30Min, All Races\n-----------------------------------\n-- Dexterity 1\n-- Vitality 2\n-- Defense % 25\n-- Defense Cap 70\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 1800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 1)\n    effect:addMod(xi.mod.VIT, 2)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 70)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/nebimonite_belt.lua"]={["Path"]="scripts/items/nebimonite_belt.lua",["SHA256"]="7f459d6dc4f00e87c8369acaf572bd2ae6ecb6f6817f09804562c77a64cbcd81",["Text"]="-----------------------------------\n-- ID: 15300\n-- nebimonite_belt\n-- Dispense: Nebimonite\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.NEBIMONITE, 1 } })\nend\n\nreturn itemObject\n"},["scripts/items/neptunes_staff.lua"]={["Path"]="scripts/items/neptunes_staff.lua",["SHA256"]="6f26b44e4381832d26b5dad5c8f85e5d0e11ad6b09e86b24c8ef52ba2560b012",["Text"]="-----------------------------------\n-- ID: 17556\n-- Item: Neptune's Staff\n-- Additional effect: water damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 25, -- guessed\n        basePower      = math.randomInt(25, 34),\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.WATER,\n        canMAB         = false,\n        canResist      = true,\n        lowestResist   = 0.5,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/nexus_cape.lua"]={["Path"]="scripts/items/nexus_cape.lua",["SHA256"]="7115026095e1f95b32680add91b95855d400bd474ed48ed1b3dd8da817146b91",["Text"]="-----------------------------------\n-- ID: 11538\n-- Item: Nexus Cape\n-- Enchantment: \"Teleport\" (Party Leader)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = xi.msg.basic.ITEM_UNABLE_TO_USE\n    local leader = target:getPartyLeader()\n    -- In a party and we were able to find the leader\n    -- (currently fails in cross map server situations)\n    if leader ~= nil and not leader:inMogHouse() then\n        -- Don't try to teleport to self!\n        if target:getID() ~= leader:getID() then\n            local leaderZone = leader:getZoneID()\n\n            -- Locations with \"**\" in comment:\n            -- ** If the party leader is located in a battlefield or other special location,\n            -- players will be forced to travel to a specific location.\n            --\n            -- Other commented locations:\n            -- Players will travel of a specific location, not that of the party leader.\n            local validZoneList =\n            {\n                xi.zone.ULEGUERAND_RANGE,\n                xi.zone.ATTOHWA_CHASM,\n                xi.zone.WEST_RONFAURE,\n                xi.zone.EAST_RONFAURE,\n                xi.zone.LA_THEINE_PLATEAU,\n                xi.zone.VALKURM_DUNES,\n                xi.zone.JUGNER_FOREST,\n                xi.zone.BATALLIA_DOWNS,\n                xi.zone.NORTH_GUSTABERG,\n                xi.zone.SOUTH_GUSTABERG,\n                xi.zone.KONSCHTAT_HIGHLANDS,\n                xi.zone.PASHHOW_MARSHLANDS,\n                xi.zone.ROLANBERRY_FIELDS,\n                xi.zone.BEAUCEDINE_GLACIER,\n                xi.zone.XARCABARD,\n                xi.zone.CAPE_TERIGGAN,\n                xi.zone.EASTERN_ALTEPA_DESERT,\n                xi.zone.WEST_SARUTABARUTA,\n                xi.zone.EAST_SARUTABARUTA,\n                xi.zone.TAHRONGI_CANYON,\n                xi.zone.BUBURIMU_PENINSULA,\n                xi.zone.MERIPHATAUD_MOUNTAINS,\n                xi.zone.SAUROMUGUE_CHAMPAIGN,\n                xi.zone.YUHTUNGA_JUNGLE,\n                xi.zone.YHOATOR_JUNGLE,\n                xi.zone.WESTERN_ALTEPA_DESERT,\n                xi.zone.QUFIM_ISLAND,\n                xi.zone.BEHEMOTHS_DOMINION,\n                xi.zone.VALLEY_OF_SORROWS,\n                xi.zone.SOUTHERN_SAN_DORIA,\n                xi.zone.NORTHERN_SAN_DORIA,\n                xi.zone.PORT_SAN_DORIA,\n                xi.zone.BASTOK_MINES,\n                xi.zone.BASTOK_MARKETS,\n                xi.zone.PORT_BASTOK,\n                xi.zone.WINDURST_WATERS,\n                xi.zone.WINDURST_WALLS,\n                xi.zone.PORT_WINDURST,\n                xi.zone.WINDURST_WOODS,\n                xi.zone.RULUDE_GARDENS,\n                xi.zone.UPPER_JEUNO,\n                xi.zone.LOWER_JEUNO,\n                xi.zone.PORT_JEUNO,\n                xi.zone.RABAO,\n                xi.zone.SELBINA,\n                xi.zone.MHAURA,\n                xi.zone.KAZHAM,\n                xi.zone.NORG,\n                xi.zone.CARPENTERS_LANDING,\n                xi.zone.BIBIKI_BAY,\n                xi.zone.LUFAISE_MEADOWS,\n                xi.zone.MISAREAUX_COAST,\n                -- xi.zone.TAVNAZIAN_SAFEHOLD,\n                xi.zone.ALTAIEU,\n                -- xi.zone.AL_ZAHBI,\n                -- xi.zone.AHT_URHGAN_WHITEGATE,\n                -- ** xi.zone.WAJAOM_WOODLANDS,\n                xi.zone.BHAFLAU_THICKETS,\n                -- xi.zone.NASHMAU,\n                -- ** xi.zone.MOUNT_ZHAYOLM,\n                -- ** xi.zone.CAEDARVA_MIRE,\n                -- xi.zone.SOUTHERN_SAN_DORIA_S,\n                xi.zone.EAST_RONFAURE_S,\n                xi.zone.JUGNER_FOREST_S,\n                xi.zone.VUNKERL_INLET_S,\n                xi.zone.BATALLIA_DOWNS_S,\n                -- xi.zone.BASTOK_MARKETS_S,\n                xi.zone.NORTH_GUSTABERG_S,\n                xi.zone.GRAUBERG_S,\n                xi.zone.PASHHOW_MARSHLANDS_S,\n                xi.zone.ROLANBERRY_FIELDS_S,\n                -- xi.zone.WINDURST_WATERS_S,\n                xi.zone.WEST_SARUTABARUTA_S,\n                xi.zone.FORT_KARUGO_NARUGO_S,\n                xi.zone.MERIPHATAUD_MOUNTAINS_S,\n                xi.zone.SAUROMUGUE_CHAMPAIGN_S,\n                xi.zone.THE_SANCTUARY_OF_ZITAH,\n                xi.zone.ROMAEVE,\n                xi.zone.RUAUN_GARDENS,\n                xi.zone.BEAUCEDINE_GLACIER_S,\n                xi.zone.XARCABARD_S,\n                -- xi.zone.METALWORKS,\n                -- xi.zone.HEAVENS_TOWER,\n                -- xi.zone.WESTERN_ADOULIN,\n                -- xi.zone.EASTERN_ADOULIN,\n                -- xi.zone.YAHSE_HUNTING_GROUNDS,\n                -- xi.zone.CEIZAK_BATTLEGROUNDS,\n                -- xi.zone.FORET_DE_HENNETIEL,\n                -- xi.zone.YORCIA_WEALD,\n                -- xi.zone.MORIMAR_BASALT_FIELDS,\n                -- xi.zone.MARJAMI_RAVINE,\n                -- xi.zone.KAMIHR_DRIFTS,\n                -- xi.zone.LEAFALLIA,\n            }\n\n            -- Make sure we can actually tele to that zone..\n            result = xi.msg.basic.ITEM_UNABLE_TO_USE_PARTY_LEADER\n\n            for _, validZone in ipairs(validZoneList) do\n                if validZone == leaderZone and target:hasVisitedZone(validZone) then\n                    result = 0\n                    break\n                end\n            end\n        end\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.LEADER, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/nimbus_cell.lua"]={["Path"]="scripts/items/nimbus_cell.lua",["SHA256"]="de7ff339fc70531b8c6190198529c126dcf1e60fa74e517d3534cd8b30b0fa5a",["Text"]="-----------------------------------\n-- Nimbus Cell\n-- 5379\n-- Removes AGI Down effect\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.salvage.onCellItemCheck(target, xi.effect.DEBILITATION, 0x008)\nend\n\nitemObject.onItemUse = function(target)\n    return xi.salvage.onCellItemUse(target, xi.effect.DEBILITATION, 0x008, 14)\nend\n\nreturn itemObject\n"},["scripts/items/ninja_die.lua"]={["Path"]="scripts/items/ninja_die.lua",["SHA256"]="3de4e0390b4ac47158ce982eb3849aeccb9c8e8de2662ad6c406b2c8ff30f686",["Text"]="-----------------------------------\n-- ID: 5489\n-- Ninja Die\n-- Teaches the job ability Ninja Roll\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnAbility(xi.jobAbility.NINJA_ROLL)\nend\n\nitemObject.onItemUse = function(target)\n    target:addLearnedAbility(xi.jobAbility.NINJA_ROLL)\nend\n\nreturn itemObject\n"},["scripts/items/noble_himantes.lua"]={["Path"]="scripts/items/noble_himantes.lua",["SHA256"]="303813b96c70c91a01fbfa6a1ec10ddccd4f8cf6b35e7defd1bb5bdf6db29315",["Text"]="-----------------------------------\n-- ID: 18755\n-- Item: Noble Himantes\n-- Item Effect: TP +100\n-- Durration: Instant\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addTP(100)\nend\n\nreturn itemObject\n"},["scripts/items/noble_lady.lua"]={["Path"]="scripts/items/noble_lady.lua",["SHA256"]="4d92fea0582010aaf581f9f065c585616d05c315ecf419d7f5c11f844ab57d48",["Text"]="-----------------------------------\n-- ID: 4485\n-- Item: noble_lady\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 3\n-- Mind -5\n-- Charisma 3\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 3)\n    effect:addMod(xi.mod.MND, -5)\n    effect:addMod(xi.mod.CHR, 3)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/nobles_bed.lua"]={["Path"]="scripts/items/nobles_bed.lua",["SHA256"]="7501ba0ae4b93dddaee587eccacca5981926f7da08c8d0efd6a55fe4a2f8fc27",["Text"]="-----------------------------------\n-- ID: 6\n-- Item: Noble's Bed\n-----------------------------------\n---@type TItemFurniture\nlocal itemObject = {}\n\nitemObject.onFurniturePlaced = function(player)\n    if player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.MOOGLES_IN_THE_WILD) == xi.questStatus.QUEST_AVAILABLE then\n        xi.quest.setVar(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.MOOGLES_IN_THE_WILD, 'bedPlacedTime', GetSystemTime())\n        xi.quest.setLocalVar(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.MOOGLES_IN_THE_WILD, 'mustZone', 1)\n    end\nend\n\nitemObject.onFurnitureRemoved = function(player)\n    xi.quest.setVar(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.MOOGLES_IN_THE_WILD, 'bedPlacedTime', 0)\nend\n\nreturn itemObject\n"},["scripts/items/noctohelix_schema.lua"]={["Path"]="scripts/items/noctohelix_schema.lua",["SHA256"]="acb005ff89ea576108ff832311cb1eddd93fc1f08e32e27dd5ea15ca8a5b2f56",["Text"]="-----------------------------------\n-- ID: 6048\n-- Noctohelix Schema\n-- Teaches the black magic Noctohelix\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.NOCTOHELIX)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.NOCTOHELIX)\nend\n\nreturn itemObject\n"},["scripts/items/nomad_cap.lua"]={["Path"]="scripts/items/nomad_cap.lua",["SHA256"]="660529938272055b256f7bd2bbdf0f27e4549e627074a5694a1c2c340ed925f6",["Text"]="-----------------------------------\n-- ID: 16119\n-- Nomad Cap\n-- Transports the user to their Home Nation\n-- TODO: Confirm wiki claims of random zone destinations among a same nation.\n-----------------------------------\nrequire('scripts/globals/teleports')\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.HOME_NATION, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/nomad_moogle_shield.lua"]={["Path"]="scripts/items/nomad_moogle_shield.lua",["SHA256"]="443ac21bfd60800600096d1b4eeec0f337dca949d48e864ea86ea51aa115c3bb",["Text"]="-----------------------------------\n-- ID: 16183\n-- Nomad Moogle Shield\n-- Enchantment: 60Min, Costume - Moogle\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 2308, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/nopales_salad.lua"]={["Path"]="scripts/items/nopales_salad.lua",["SHA256"]="9e385eccdea10cbc54b0227b2e6410d7dff8345a0654d9fef84e4b2d219af3c1",["Text"]="-----------------------------------\n-- ID: 5701\n-- Item: nopales_salad\n-- Food Effect: 3Hrs, All Races\n-----------------------------------\n-- Strength 1\n-- Agility 6\n-- Ranged Accuracy +20\n-- Ranged Attack +10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 1)\n    effect:addMod(xi.mod.AGI, 6)\n    effect:addMod(xi.mod.RACC, 20)\n    effect:addMod(xi.mod.RATT, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/nopales_salad_+1.lua"]={["Path"]="scripts/items/nopales_salad_+1.lua",["SHA256"]="050e7a3fe4b699b5f04943a1662c4d068104a8daeaf685941a7e5a8943b1fb48",["Text"]="-----------------------------------\n-- ID: 5702\n-- Item: Nopales Salad +1\n-- Food Effect: 3Hrs, All Races\n-----------------------------------\n-- Strength 2\n-- Agility 7\n-- Ranged Accuracy +25\n-- Ranged Attack +15\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 2)\n    effect:addMod(xi.mod.AGI, 7)\n    effect:addMod(xi.mod.RACC, 25)\n    effect:addMod(xi.mod.RATT, 15)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/norg_earring.lua"]={["Path"]="scripts/items/norg_earring.lua",["SHA256"]="76f52af8c65dcf0854701ccd1c7090b2ac121a84e6999d56b4ffb6ba55f9cee1",["Text"]="-----------------------------------\n-- ID: 16047\n-- Norg Earring\n-- Enchantment: \"Teleport\" (Norg)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.NORG_EARRING, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/northern_san_doria_gate_glyph.lua"]={["Path"]="scripts/items/northern_san_doria_gate_glyph.lua",["SHA256"]="9bd70cf22ad0992e1a611070942443565bb925b81e718533a9b22598b044e970",["Text"]="-----------------------------------\n-- ID: 4192\n-- Northern San d'Oria Gate Glyph\n-- Transports the user to the Northern San d'Oria gate\n-- (near Achantere, T.K.)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.NORTH_SANDY_GLYPH, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/nosteau_herring.lua"]={["Path"]="scripts/items/nosteau_herring.lua",["SHA256"]="37be77a731ede7279731d638cbfb846a161d088884e8d38d75f27596b9f5b951",["Text"]="-----------------------------------\n-- ID: 4482\n-- Item: nosteau_herring\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/novennial_ring.lua"]={["Path"]="scripts/items/novennial_ring.lua",["SHA256"]="90e2f4d1645e9d566e8979e61ca2ffe7ed3789292c22b0af2ac70d96c224dbe8",["Text"]="-----------------------------------\n-- ID: 11666\n-- Item: novennial ring\n-- Experience point bonus\n-----------------------------------\n-- Bonus: +100%\n-- Duration: 720 min\n-- Max bonus: 9000 exp\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if target:hasStatusEffect(xi.effect.DEDICATION) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target)\n    local effect    = xi.effect.DEDICATION\n    local power     = 100\n    local duration  = 43200\n    local subpower  = 9000\n\n    xi.itemUtils.addItemExpEffect(target, effect, power, duration, subpower)\nend\n\nreturn itemObject\n"},["scripts/items/oberon_bullet_pouch.lua"]={["Path"]="scripts/items/oberon_bullet_pouch.lua",["SHA256"]="0f24a13b86acb3b83d52d57156eed1c3ff17fd12bc55c400ec71dce498b0cd00",["Text"]="-----------------------------------\n-- ID: 5822\n-- Oberon Bullet Pouch\n-- When used, you will obtain one stack of Oberon Bullets\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.OBERON_BULLET, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/ogre_eel.lua"]={["Path"]="scripts/items/ogre_eel.lua",["SHA256"]="e84415a7e76fdf1fe0c9755782a0c8a139f8a901221e2e0e1f7a88ed2687c8c6",["Text"]="-----------------------------------\n-- ID: 4481\n-- Item: ogre_eel\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity 2\n-- Mind -4\n-- Evasion 5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, 2)\n    effect:addMod(xi.mod.MND, -4)\n    effect:addMod(xi.mod.EVA, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/ojo_rice_ball.lua"]={["Path"]="scripts/items/ojo_rice_ball.lua",["SHA256"]="68e94fd40bf4d9fd23ae12effffc04dd429b995482897ffce0e6d4322b8cbcb5",["Text"]="-----------------------------------\n-- ID: 5929\n-- Item: Ojo Rice Ball\n-- Food Effect: 60 Mins, All Races\n-----------------------------------\n-- HP +50\n-- Dexterity +5\n-- Vitality +5\n-- Character +5\n-- Effect with enhancing equipment (Note: these are latents on gear with the effect)\n-- Attack +60\n-- Defense +40\n-- Triple Attack +2%\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 50)\n    effect:addMod(xi.mod.DEX, 5)\n    effect:addMod(xi.mod.VIT, 5)\n    effect:addMod(xi.mod.CHR, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/old_bolt_box.lua"]={["Path"]="scripts/items/old_bolt_box.lua",["SHA256"]="d99a93106e698e4b8ce2a86c5363b64b2b91996a7e4a6f910e2825c3d7dff1d5",["Text"]="-----------------------------------\n-- ID: 5278\n-- Old Bolt Box\n-- When used, you will obtain one partial stack of Dogbolt\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DOGBOLT, math.randomInt(10, 20) } })\nend\n\nreturn itemObject\n"},["scripts/items/old_bolt_box_+1.lua"]={["Path"]="scripts/items/old_bolt_box_+1.lua",["SHA256"]="436d2f4a6236df5e75f9e96726da7ae55e80e71cde659348d2089886f1d2c9c1",["Text"]="-----------------------------------\n-- ID: 5279\n-- Old Bolt Box +1\n-- When used, you will obtain one partial stack of Dogbolt +1\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DOGBOLT_P1, math.randomInt(10, 20) } })\nend\n\nreturn itemObject\n"},["scripts/items/old_bolt_box_+2.lua"]={["Path"]="scripts/items/old_bolt_box_+2.lua",["SHA256"]="1d9fb12498616b640fcfd68b3550b90e173c9d00ac6c3bfa8df72c1ebe5553bd",["Text"]="-----------------------------------\n-- ID: 5280\n-- Old Bolt Box +2\n-- When used, you will obtain one partial stack of Dogbolt +2\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.DOGBOLT_P2, math.randomInt(10, 20) } })\nend\n\nreturn itemObject\n"},["scripts/items/old_bolt_box_+3.lua"]={["Path"]="scripts/ite